#nullable enable

using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;

namespace Campground.Shared.Contracts
{
    /// <summary>
    /// §3.8 — one key per film or episode, so the same film reached through a FieldGuide library or an
    /// alternate version counts as the same film. Provider IDs first (TMDb, TVDb, IMDb), then the path.
    /// </summary>
    internal static class MediaIdentity
    {
        private static readonly string[] Order = { "Tmdb", "Tvdb", "Imdb" };

        /// <summary>Key for a film or any single item.</summary>
        internal static string KeyFor(IReadOnlyDictionary<string, string>? providerIds, string? path)
        {
            var id = FirstProviderId(providerIds);
            return id ?? PathKey(path);
        }

        /// <summary>
        /// Key for a whole series (for example, a choice carried across its episodes). Use this rather than
        /// <see cref="KeyFor"/> on the series item: TMDb and TVDb number films and series separately, so film
        /// 550 and series 550 would otherwise get the same key.
        /// </summary>
        internal static string KeyForSeries(IReadOnlyDictionary<string, string>? seriesProviderIds, string? path)
            => "series:" + KeyFor(seriesProviderIds, path);

        /// <summary>Key for an episode: the series' identity plus season and episode numbers.</summary>
        internal static string KeyForEpisode(IReadOnlyDictionary<string, string>? seriesProviderIds, int? season, int? episode, string? path)
        {
            var series = FirstProviderId(seriesProviderIds);
            if (series == null || season == null || episode == null)
            {
                return PathKey(path);
            }

            return $"{series}:s{season.Value}e{episode.Value}";
        }

        private static string? FirstProviderId(IReadOnlyDictionary<string, string>? ids)
        {
            if (ids == null)
            {
                return null;
            }

            foreach (var name in Order)
            {
                foreach (var pair in ids)
                {
                    if (string.Equals(pair.Key, name, StringComparison.OrdinalIgnoreCase) && !string.IsNullOrWhiteSpace(pair.Value))
                    {
                        return name.ToLowerInvariant() + ":" + pair.Value.Trim();
                    }
                }
            }

            return null;
        }

        private static string PathKey(string? path)
        {
            var normalized = (path ?? string.Empty).Replace('\\', '/').Trim().ToLowerInvariant();
            if (normalized.Length == 0)
            {
                return "unknown";
            }

            return "path:" + Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(normalized)), 0, 12).ToLowerInvariant();
        }
    }
}
